{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law cap, interest and return rules","requirement":"A landlord may not demand a security deposit above one and one-half times one month's rent, must hold it in trust in an insured New Jersey account and pay the tenant the interest earned, and must return it with interest less deductions within 30 days after the tenancy ends.","key_value":"1.5 months' rent; yearly deposit increase max 10%","coverage_conditions":"All residential rental units in New Jersey. Deposit-holding account rules differ for landlords receiving deposits for 10 or fewer units versus 10 or more units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Covers all NJ residential rentals; account type differs by landlord's 10-or-fewer vs 10-or-more units"},"exemptions":"Seasonal use or rental, meaning a term of not more than 125 consecutive days by a person with a permanent residence elsewhere, is exempt from the security deposit account provisions.","penalty":"If the deposit is not returned within 30 days or the tenant disputes deductions, the tenant may sue for double the amount wrongfully withheld, plus court costs and reasonable attorney's fees.","effective_date":null,"citation":"N.J.S.A. 46:8-19 et seq.","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic-violence termination","requirement":"When a tenant terminates a lease under the Safe Housing Act because of domestic violence, the landlord must make the security deposit and interest available within 15 business days and, within three business days, notify the tenant in writing where and when to collect it.","key_value":"15 business days","coverage_conditions":"Tenancies terminated under the Safe Housing Act (N.J.S.A. 46:8-9.4 et seq.) because of domestic violence.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Applies only where a tenancy is terminated under the Safe Housing Act for domestic violence; excludes transient or seasonal rentals"},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
